var tooltipTriggerList=[].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]')),tooltipList=tooltipTriggerList.map((function(tooltipTriggerEl){return new bootstrap.Tooltip(tooltipTriggerEl)}));function virar_card(card){console.log(card),card.classList.toggle("is-flipped"),card.classList.toggle("not-flipped")}function alterar_resposta(btn,id){resposta=document.getElementById(id),resposta.classList.contains("d-none")?(resposta.classList.remove("d-none"),btn.innerText="X"):(resposta.classList.add("d-none"),btn.innerText="Ver resposta")}function sair(){confirm("Deseja mesmo sair?")&&window.close()}function mostrar_legenda(id){legenda=document.getElementById(id),legenda.classList.toggle("d-none"),legenda.classList.toggle("d-block")}const elements=document.querySelectorAll("[data-animation]");function handleScroll(){const screenPosition=window.innerHeight/1.5;elements.forEach(element=>{const elementPosition=element.getBoundingClientRect().top,elementBottom=element.getBoundingClientRect().bottom;elementPosition<screenPosition&&elementBottom>0?element.classList.add("active"):element.classList.remove("active")})}window.addEventListener("scroll",handleScroll);